-- DeadTrigger2(AU)[32+64]-v15.01--Nobita
-- Khong sua file nay. Moi thay doi lam hong bo giai ma.
local _uoojmh = 136
local _mdcukh = 190
local _gyguff = 149
local _grqucs = ""

local _ifztjn = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _piliqj(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _nsmawq(d)
	d = d:gsub("[^" .. _ifztjn .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_ifztjn:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _tcsgdb = _nsmawq(_grqucs)
local _ilicud = { _uoojmh, _mdcukh, _gyguff }
local _abopsc = {}
for i = 1, #_tcsgdb do
	_abopsc[i] = string.char(_piliqj(_tcsgdb:byte(i), _ilicud[(i - 1) % 3 + 1]))
end

local _isejdf = load or loadstring
local _xgrenl, _lckomi = _isejdf(table.concat(_abopsc), "=w")
if not _xgrenl then
	gg.alert("File hong: " .. tostring(_lckomi))
	os.exit()
end
_xgrenl()
